/** Biblioteca educativa. Possíveis causas não são diagnósticos definitivos. */
(function (lab) {
  const microsoft = {
    performance: 'https://support.microsoft.com/pt-BR/Windows/Experience/Performance-Optimization/tips-to-improve-pc-performance-in-windows',
    wifi: 'https://support.microsoft.com/pt-br/windows/experience/connectivity-networking/fix-wi-fi-connection-issues-in-windows',
    security: 'https://support.microsoft.com/pt-br/windows/security/threat-malware-protection/virus-and-threat-protection-in-the-windows-security-app',
    printer: 'https://support.microsoft.com/pt-br/windows/hardware/printer/fix-printer-connection-and-printing-problems-in-windows'
  };
  lab.supportProblems = [
    {id:'slow',name:'Computador muito lento',symptoms:'Aplicativos demoram para abrir, cliques levam tempo para responder ou o disco fica ocupado.',causes:['Muitos aplicativos abertos ou iniciando juntos.','Pouco espaço livre ou consumo elevado de memória, CPU ou disco.'],steps:['Salve seu trabalho e feche aplicativos que não está usando.','Abra o Gerenciador de Tarefas com Ctrl + Shift + Esc e observe quais aplicativos consomem mais recursos, sem encerrar processos desconhecidos.','Confira o espaço livre e as atualizações disponíveis. Antes de remover arquivos, confira o conteúdo e mantenha cópia dos arquivos importantes.'],help:'Se continuar lento com poucos aplicativos abertos, relate quando começou e o que estava em uso.',source:microsoft.performance},
    {id:'power',name:'Computador não liga',symptoms:'Ao apertar o botão, não aparecem luzes, som ou imagem.',causes:['Tomada, cabo ou carregador sem alimentação.','Problema de energia, bateria ou outro componente; tela sem imagem também pode parecer falta de energia.'],steps:['Observe se há luzes ou sons; informe isso ao técnico.','Confira se os cabos externos estão conectados e se a tomada funciona com outro aparelho seguro. Use somente carregador compatível.','Se houver cheiro de queimado, líquido ou bateria deformada, interrompa o uso e procure assistência. Não abra a fonte ou o equipamento.'],help:'Sem sinais de energia após conferir as conexões, peça avaliação técnica antes de trocar peças.'},
    {id:'freeze',name:'Windows travando',symptoms:'A tela congela, aplicativos param de responder ou o sistema reinicia inesperadamente.',causes:['Aplicativo com falha, atualização pendente ou recursos sobrecarregados.','Drivers, armazenamento, temperatura ou hardware também podem estar envolvidos.'],steps:['Se o sistema ainda responder, salve os arquivos e anote qual aplicativo estava aberto.','Aguarde um pouco para descartar uma tarefa em andamento; tente abrir o Gerenciador de Tarefas.','Após recuperar o acesso, confira atualizações oficiais e observe se o problema acontece com um aplicativo específico. Evite desligamentos forçados repetidos.'],help:'Travamentos recorrentes ou perda de arquivos precisam de avaliação; preserve uma cópia dos dados.',source:microsoft.performance},
    {id:'internet',name:'Internet não funciona',symptoms:'Sites e aplicativos não conectam mesmo com o Wi-Fi ou cabo conectado.',causes:['Falha no roteador ou no provedor.','Configuração local, sinal ou falha restrita a um aplicativo.'],steps:['Teste outro site e outro dispositivo para saber se a falha é geral.','Confira o cabo, o Wi-Fi e se o modo avião está desativado.','Se for adequado, reinicie o roteador sem apertar o botão de restauração de fábrica. Aguarde e teste novamente.'],help:'Se nenhum dispositivo conectar, consulte o provedor. Se apenas um falhar, informe isso ao técnico.',source:microsoft.wifi},
    {id:'wifi',name:'Wi-Fi desconectando',symptoms:'A conexão cai e volta, fica fraca ou funciona apenas perto do roteador.',causes:['Distância, obstáculos ou interferência no sinal.','Roteador, adaptador ou driver podem precisar de investigação.'],steps:['Teste o dispositivo mais perto do roteador e observe se estabiliza.','Compare com outro dispositivo no mesmo local.','Confira atualizações oficiais do sistema e do fabricante; não instale pacotes de drivers de sites desconhecidos.'],help:'Informe se a queda ocorre em todos os aparelhos ou somente em um.',source:microsoft.wifi},
    {id:'malware',name:'Suspeita de vírus',symptoms:'Janelas inesperadas, programas desconhecidos, redirecionamentos ou alertas de segurança.',causes:['Extensão ou aplicativo indesejado.','Malware é uma possibilidade, mas esses sintomas sozinhos não confirmam infecção.'],steps:['Não clique nos alertas suspeitos nem informe senhas em janelas inesperadas.','Abra a Segurança do Windows pelo menu do sistema, atualize a proteção e execute uma verificação.','Anote o alerta exibido. Não desative o antivírus e não instale limpadores desconhecidos.'],help:'Se houver suspeita de conta comprometida, use outro dispositivo confiável para revisar o acesso. Não envie senhas ao técnico.',source:microsoft.security},
    {id:'bluescreen',name:'Tela azul do Windows',symptoms:'Uma tela de erro interrompe o Windows e pode reiniciar o computador.',causes:['Driver, atualização ou aplicativo incompatível.','Falha de hardware ou armazenamento também é possível; o código de erro ajuda na investigação.'],steps:['Fotografe ou anote o código de parada, sem incluir dados pessoais na imagem.','Informe se começou após instalar um programa, atualizar ou conectar um dispositivo.','Se conseguir usar o computador, faça cópia dos arquivos importantes e confira atualizações oficiais. Não formate ou troque peças com base apenas na cor da tela.'],help:'Se o erro se repetir ou impedir o acesso, procure avaliação técnica com o código da tela.'},
    {id:'apps',name:'Programas que não abrem',symptoms:'Um aplicativo fecha sozinho, não inicia ou mostra uma mensagem de erro.',causes:['Atualização incompleta, arquivo do aplicativo danificado ou incompatibilidade.','Falta de recursos ou falha específica do aplicativo.'],steps:['Anote a mensagem exata e teste se outros aplicativos abrem.','Salve seu trabalho e reinicie o computador normalmente.','Confira atualizações pelo aplicativo ou site oficial. Antes de reinstalar, preserve dados, configurações e licenças.'],help:'Envie o nome do programa e a mensagem apresentada, sem chaves de licença ou senhas.'},
    {id:'input',name:'Problemas com teclado e mouse',symptoms:'Teclas, cliques ou movimentos não respondem, falham ou se repetem.',causes:['Conexão, bateria ou receptor sem fio.','Configuração, driver ou defeito no periférico.'],steps:['Confira conexão, bateria e receptor, quando existirem.','Teste outra porta USB e, se possível, outro periférico.','Observe se o problema ocorre em todos os aplicativos. Não desmonte o dispositivo para fazer o teste inicial.'],help:'Informe se é USB, Bluetooth ou integrado ao notebook, e se outro periférico funciona.'},
    {id:'printer',name:'Problemas com impressora',symptoms:'Documentos ficam na fila, a impressora aparece offline ou não imprime.',causes:['Cabo ou rede desconectados, impressora incorreta selecionada.','Papel, suprimentos, fila ou software da impressora.'],steps:['Confira energia, papel e mensagens no painel da impressora.','Verifique o cabo ou a rede e se a impressora correta foi selecionada.','Confira a fila de impressão. Para atolamentos ou instalação, siga as instruções oficiais do modelo e não force as peças.'],help:'Informe marca, modelo, tipo de conexão e mensagem do painel.',source:microsoft.printer},
    {id:'heat',name:'Computador superaquecendo',symptoms:'Muito calor, ventoinha alta, redução de desempenho ou desligamentos durante o uso.',causes:['Ventilação obstruída ou ambiente quente.','Carga intensa, poeira ou falha de refrigeração são possibilidades.'],steps:['Interrompa tarefas pesadas e deixe o equipamento esfriar.','Use uma superfície firme e mantenha as saídas de ar livres; evite cobertores e almofadas.','Se houver desligamentos, cheiro incomum ou bateria deformada, interrompa o uso e procure assistência. Não abra o equipamento quente.'],help:'Calor ao toque não confirma sozinho uma falha. Informe quando acontece e se há desligamentos.'},
    {id:'other',name:'Outros problemas',symptoms:'O problema não se encaixa nas categorias anteriores.',causes:['As causas dependem do sintoma, do equipamento e das mudanças recentes.'],steps:['Anote o que aparece na tela e quando acontece.','Informe o modelo do equipamento e o que mudou antes da falha.','Evite formatar, apagar arquivos ou alterar configurações desconhecidas antes da avaliação.'],help:'Descreva o comportamento no formulário abaixo para preparar uma solicitação de ajuda.'}
  ];
  lab.supportLevels = {light:'Leve: ainda consigo utilizar o equipamento.',medium:'Intermediária: o problema atrapalha o uso.',severe:'Grave: não consigo utilizar o equipamento.'};
  lab.supportDurations = {today:'Começou hoje.',days:'Há 2 a 3 dias.',week:'Há aproximadamente uma semana.',month:'Há mais de um mês.',other:'Outro período'};
  lab.supportDevices = {desktop:'Computador',notebook:'Notebook',other:'Outro dispositivo'};

  lab.supportMessage = function (fields) {
    const problem = lab.supportProblems.find(problem => problem.id === fields.problem);
    if (!problem || !Object.hasOwn(lab.supportLevels, fields.level) || !Object.hasOwn(lab.supportDurations, fields.duration) || !Object.hasOwn(lab.supportDevices, fields.device)) throw new Error('Selecione problema, dificuldade, período e equipamento.');
    const description = String(fields.description || '').trim();
    const period = fields.duration === 'other' ? String(fields.otherPeriod || '').trim() : lab.supportDurations[fields.duration];
    const device = fields.device === 'other' ? String(fields.otherDevice || '').trim() : lab.supportDevices[fields.device];
    if (!description || !period || !device) throw new Error('Preencha a descrição e os detalhes de período ou equipamento quando selecionar Outro.');
    if (description.length > 1500 || period.length > 100 || device.length > 100 || String(fields.tried || '').length > 800) throw new Error('Resuma os campos para preparar a mensagem.');
    return ['Olá, Miguel! Gostaria de solicitar suporte técnico.','',
      'Problema: ' + problem.name,
      'Dificuldade: ' + lab.supportLevels[fields.level],
      'Há quanto tempo: ' + period,
      'Equipamento: ' + device,
      '', 'Descrição: ' + description,
      '', 'O que já tentei: ' + (String(fields.tried || '').trim() || 'Ainda não informei tentativas.')
    ].join('\n');
  };
})(window.StackLab);
